/// <summary>
///    Finds the specified record in the <c>KCS_KBVCompPrio</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>KCS_KBVCompPrioId</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVCompPrio</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVCompPrio find( KCS_KBVCompPrioId   _recordId,
                                    boolean             _forUpdate = false)
{
    KCS_KBVCompPrio record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint IdIdx
        where   record.Id == _recordId;
    }

    return record;
}

/// <summary>
///    AVA <c>findDataAreaId</c> method.
/// </summary>
/// <param name="_recordId">
///    <c>DataAreaId</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVCompPrio</c> as return value
/// </returns>
public static KCS_KBVCompPrio findDataAreaId(   DataAreaId  _recordId,
                                                boolean     _forUpdate = false)
{
    KCS_KBVCompPrio record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        order by Id
        where   record.Company == _recordId;
    }

    return record;
}
